/**
 * The schema. Rules it keeps: every table's key starts with `org_id`; ids are UUIDv7 made by the
 * application; every timestamp is a parameter from the clock; there are no triggers and no
 * sequences. Search columns on `facts` are generated by PostgreSQL from the text.
 *
 * A column that holds a code has a CHECK that lists its values; a test compares each list with
 * the one the code declares. Who performed an act is two columns everywhere, `…_person` (a
 * principal's id) and `…_job` (`name:runner`), exactly one of them set.
 *
 * Foreign keys stay on one side of the line between the directory tables and the data tables,
 * which are never joined. A data row that carries its parent's `audience_id` is tied to the
 * parent by a key that includes it, so the two cannot disagree, and follows it (`ON UPDATE
 * CASCADE`) when the parent changes audience: a fact or a task moves with everything that hangs
 * off it. The log does not move: an entry stays in the log it was written in.
 */
import { sql } from "kysely";
import type { Migration } from "kysely/migration";

const EXTENSIONS = [
  sql`CREATE EXTENSION IF NOT EXISTS vector`,
  sql`CREATE EXTENSION IF NOT EXISTS pg_trgm`,
];

/** Directory: people, their tokens, audiences, projects and sessions. */
const DIRECTORY = [
  sql`CREATE TABLE principals (
    org_id uuid NOT NULL,
    id uuid NOT NULL,
    display_name text NOT NULL,
    subject text NOT NULL,                    -- what the identity provider knows the principal by
    PRIMARY KEY (org_id, id)
  )`,
  sql`CREATE UNIQUE INDEX principals_by_subject ON principals (subject)`,

  sql`CREATE TABLE credentials (
    org_id uuid NOT NULL,
    id uuid NOT NULL,
    principal_id uuid NOT NULL,
    kind text NOT NULL CHECK (kind IN ('agent', 'person')),  -- what it opens: the tools, or the dashboard
    label text NOT NULL,
    token_hash bytea NOT NULL,                -- SHA-256 of the secret; the secret is never stored
    created_at timestamptz NOT NULL,
    last_used_at timestamptz,                 -- stamped at most once a minute
    revoked_at timestamptz,
    PRIMARY KEY (org_id, id),
    FOREIGN KEY (org_id, principal_id) REFERENCES principals (org_id, id) ON DELETE CASCADE
  )`,
  sql`CREATE UNIQUE INDEX credentials_by_token_hash ON credentials (token_hash)`,

  sql`CREATE TABLE audiences (
    org_id uuid NOT NULL,
    id uuid NOT NULL,
    kind text NOT NULL CHECK (kind IN ('private', 'shared')),
    owner_id uuid,                            -- the person, for a private audience
    PRIMARY KEY (org_id, id),
    FOREIGN KEY (org_id, owner_id) REFERENCES principals (org_id, id),
    CONSTRAINT audiences_owner_when_private CHECK ((kind = 'private') = (owner_id IS NOT NULL))
  )`,
  sql`CREATE UNIQUE INDEX audiences_private_by_owner ON audiences (org_id, owner_id) WHERE kind = 'private'`,
  // What everyone on the server sees: made when a second person is added, and never before.
  sql`CREATE UNIQUE INDEX audiences_one_shared ON audiences (org_id) WHERE kind = 'shared'`,

  // One row per audience: the write lock of its units and the sequence of its events.
  sql`CREATE TABLE audience_head (
    org_id uuid NOT NULL,
    audience_id uuid NOT NULL,
    last_seq bigint NOT NULL,
    PRIMARY KEY (org_id, audience_id),
    FOREIGN KEY (org_id, audience_id) REFERENCES audiences (org_id, id) ON DELETE CASCADE
  )`,

  sql`CREATE TABLE projects (
    org_id uuid NOT NULL,
    key text NOT NULL,                        -- host/owner/name, or <owner>/<slug>
    kind text NOT NULL CHECK (kind IN ('repository', 'named')),
    created_at timestamptz NOT NULL,
    PRIMARY KEY (org_id, key)
  )`,

  // A person's own choice for a project, and their own name for it. No row: not chosen yet, and
  // the project is private. Nothing here is another person's to read.
  sql`CREATE TABLE project_choices (
    org_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    project text NOT NULL,
    treatment text NOT NULL CHECK (treatment IN ('private', 'shared')),
    display_name text,
    PRIMARY KEY (org_id, principal_id, project),
    FOREIGN KEY (org_id, principal_id) REFERENCES principals (org_id, id) ON DELETE CASCADE,
    FOREIGN KEY (org_id, project) REFERENCES projects (org_id, key)
  )`,

  // Inferred by the server; no call passes one.
  sql`CREATE TABLE sessions (
    org_id uuid NOT NULL,
    id uuid NOT NULL,
    principal_id uuid NOT NULL,
    display_id text NOT NULL,
    client_name text NOT NULL,
    client_version text,
    conversation_id text,
    project text,                             -- the project's key; NULL for calls refused for a missing project
    first_call_at timestamptz NOT NULL,
    last_call_at timestamptz NOT NULL,
    last_search_at timestamptz,
    last_publish_at timestamptz,
    refused_calls integer NOT NULL,
    calls integer NOT NULL,                   -- accepted calls
    briefed_at timestamptz,                   -- when a result carried the session's brief
    note_text text,                           -- the session's one note; a later one replaces it
    note_final boolean,                       -- a final note ends the session
    note_at timestamptz,
    PRIMARY KEY (org_id, id),
    FOREIGN KEY (org_id, principal_id) REFERENCES principals (org_id, id) ON DELETE CASCADE,
    FOREIGN KEY (org_id, project) REFERENCES projects (org_id, key),
    CONSTRAINT sessions_note_whole CHECK (num_nonnulls(note_text, note_final, note_at) IN (0, 3))
  )`,
  sql`CREATE INDEX sessions_by_key ON sessions (org_id, principal_id, client_name, last_call_at)`,
  sql`CREATE INDEX sessions_by_project ON sessions (org_id, principal_id, project, last_call_at)`,
];

/** Facts and what hangs off them. Every statement filters on `org_id` and a list of audiences. */
const FACTS = [
  sql`CREATE TABLE facts (
    org_id uuid NOT NULL,
    id uuid NOT NULL,
    audience_id uuid NOT NULL,
    project text NOT NULL,                    -- the project's key
    claim text,                               -- NULL in a stub
    detail text,
    question text,
    citations jsonb,
    status text NOT NULL CHECK (status IN ('unconfirmed', 'confirmed', 'superseded')),
    author uuid NOT NULL,                     -- always a person
    content_hash bytea NOT NULL,
    claim_hash bytea NOT NULL,
    superseded_by uuid,                       -- the fact that replaced this one: the next link of its chain
    vector halfvec(384),                      -- NULL until embedded
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    redacted_at timestamptz,                  -- who redacted it is the actor of its FactRedacted event
    search_text text GENERATED ALWAYS AS (lower(coalesce(claim, '') || ' ' || coalesce(detail, ''))) STORED,
    tsv tsvector GENERATED ALWAYS AS (
      setweight(to_tsvector('english', coalesce(claim, '')), 'A') ||
      setweight(to_tsvector('english', coalesce(detail, '')), 'B') ||
      setweight(to_tsvector('english', coalesce(question, '')), 'C')
    ) STORED,
    PRIMARY KEY (org_id, id),
    UNIQUE (org_id, audience_id, id),
    FOREIGN KEY (org_id, audience_id, superseded_by) REFERENCES facts (org_id, audience_id, id)
      ON UPDATE CASCADE,
    CONSTRAINT facts_superseded_by_another CHECK (superseded_by <> id),
    CONSTRAINT facts_superseded_has_successor CHECK ((status = 'superseded') = (superseded_by IS NOT NULL))
  )`,
  sql`CREATE INDEX facts_by_audience ON facts (org_id, audience_id, updated_at)`,
  sql`CREATE INDEX facts_by_claim_hash ON facts (org_id, audience_id, author, claim_hash)`,
  sql`CREATE INDEX facts_by_project ON facts (org_id, audience_id, project, updated_at)`,
  sql`CREATE INDEX facts_by_successor ON facts (org_id, superseded_by) WHERE superseded_by IS NOT NULL`,

  // Normalized identifiers per fact, for the identifier pass.
  sql`CREATE TABLE fact_idents (
    org_id uuid NOT NULL,
    fact_id uuid NOT NULL,
    ident text NOT NULL,
    PRIMARY KEY (org_id, fact_id, ident),
    FOREIGN KEY (org_id, fact_id) REFERENCES facts (org_id, id) ON DELETE CASCADE
  )`,
  sql`CREATE INDEX fact_idents_by_ident ON fact_idents (org_id, ident)`,

  // The facts a fact cites: how the facts that rest on a fact are found.
  sql`CREATE TABLE cited_facts (
    org_id uuid NOT NULL,
    fact_id uuid NOT NULL,
    cited_fact uuid NOT NULL,
    PRIMARY KEY (org_id, fact_id, cited_fact),
    FOREIGN KEY (org_id, fact_id) REFERENCES facts (org_id, id) ON DELETE CASCADE,
    FOREIGN KEY (org_id, cited_fact) REFERENCES facts (org_id, id) ON DELETE CASCADE
  )`,
  sql`CREATE INDEX cited_facts_by_cited ON cited_facts (org_id, cited_fact)`,

  // One row per person and fact.
  sql`CREATE TABLE confirmations (
    org_id uuid NOT NULL,
    fact_id uuid NOT NULL,
    person uuid NOT NULL,
    audience_id uuid NOT NULL,
    at timestamptz NOT NULL,
    source_version text,
    checked text,
    PRIMARY KEY (org_id, fact_id, person),
    FOREIGN KEY (org_id, audience_id, fact_id) REFERENCES facts (org_id, audience_id, id)
      ON UPDATE CASCADE ON DELETE CASCADE
  )`,

  sql`CREATE TABLE flags (
    org_id uuid NOT NULL,
    id uuid NOT NULL,
    audience_id uuid NOT NULL,
    fact_id uuid NOT NULL,
    kind text NOT NULL CHECK (
      kind IN ('possible_duplicate', 'possible_contradiction', 'source_changed', 'marked_stale')
    ),
    raised_by_person uuid,
    raised_by_job text,
    at timestamptz NOT NULL,
    cleared_at timestamptz,
    PRIMARY KEY (org_id, id),
    FOREIGN KEY (org_id, audience_id, fact_id) REFERENCES facts (org_id, audience_id, id)
      ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT flags_raised_by_one CHECK (num_nonnulls(raised_by_person, raised_by_job) = 1)
  )`,
  // One open flag of a kind per fact and raiser.
  sql`CREATE UNIQUE INDEX flags_one_open
    ON flags (org_id, fact_id, kind, coalesce(raised_by_person::text, raised_by_job))
    WHERE cleared_at IS NULL`,
];

/** The log, the rulings a job or a person made, and the follow-up jobs of a unit. */
const LOG = [
  // Append-only per audience; ids, kinds and hashes, never text. An entry stays where it was
  // written when its subject moves: the move itself is an entry in both logs.
  sql`CREATE TABLE events (
    org_id uuid NOT NULL,
    audience_id uuid NOT NULL,
    seq bigint NOT NULL,
    at timestamptz NOT NULL,
    actor_person uuid,
    actor_job text,
    session uuid,                             -- NULL when no tool call caused the event
    kind text NOT NULL CHECK (
      kind IN (
        'FactPublished', 'FactRewritten', 'FactSuperseded', 'FactConfirmed', 'FactRedacted',
        'FactShared', 'FactWithdrawn', 'FlagRaised', 'FlagCleared', 'RulingReverted',
        'TaskPublished', 'TaskClaimed', 'TaskReleased', 'TaskDone', 'TaskNoted',
        'TaskShared', 'TaskWithdrawn'
      )
    ),
    subject uuid NOT NULL,                    -- the fact, task or ruling the event is about
    payload jsonb NOT NULL,
    PRIMARY KEY (org_id, audience_id, seq),
    CONSTRAINT events_actor_one CHECK (num_nonnulls(actor_person, actor_job) = 1)
  )`,
  // What the logs hold about one record, read across the logs a reader may see, in time order.
  sql`CREATE INDEX events_by_subject ON events (org_id, subject, at)`,

  // One row per decision a person or a job made about a fact; codes, never text. It moves with
  // its fact; the event it wrote stays in its log and names the ruling in its payload.
  sql`CREATE TABLE rulings (
    org_id uuid NOT NULL,
    id uuid NOT NULL,
    audience_id uuid NOT NULL,
    decision text NOT NULL CHECK (decision IN ('merge_duplicate', 'revert')),
    fact_id uuid NOT NULL,
    decided_by_person uuid,
    decided_by_job text,
    reasons jsonb NOT NULL,
    reverted_by uuid,                         -- the ruling that undid this one, recorded after it is named here
    at timestamptz NOT NULL,
    PRIMARY KEY (org_id, id),
    FOREIGN KEY (org_id, audience_id, fact_id) REFERENCES facts (org_id, audience_id, id)
      ON UPDATE CASCADE,
    FOREIGN KEY (org_id, reverted_by) REFERENCES rulings (org_id, id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT rulings_decided_by_one CHECK (num_nonnulls(decided_by_person, decided_by_job) = 1)
  )`,
  sql`CREATE INDEX rulings_by_audience ON rulings (org_id, audience_id, at)`,
  sql`CREATE INDEX rulings_by_fact ON rulings (org_id, fact_id)`,

  sql`CREATE TABLE outbox (
    org_id uuid NOT NULL,
    id uuid NOT NULL,
    audience_id uuid NOT NULL,
    kind text NOT NULL CHECK (kind IN ('embed', 'consolidate')),
    subject uuid NOT NULL,                    -- the fact the job is about
    run_after timestamptz NOT NULL,
    attempts integer NOT NULL DEFAULT 0,
    locked_until timestamptz,
    dead boolean NOT NULL DEFAULT false,
    PRIMARY KEY (org_id, id),
    FOREIGN KEY (org_id, audience_id, subject) REFERENCES facts (org_id, audience_id, id)
      ON UPDATE CASCADE ON DELETE CASCADE
  )`,
  sql`CREATE INDEX outbox_due ON outbox (run_after) WHERE NOT dead`,
];

const TASKS = [
  sql`CREATE TABLE tasks (
    org_id uuid NOT NULL,
    id uuid NOT NULL,
    audience_id uuid NOT NULL,
    project text NOT NULL,                    -- the project's key
    title text NOT NULL,
    description text,
    state text NOT NULL CHECK (state IN ('open', 'claimed', 'handed_off', 'done')),
    version integer NOT NULL,
    tracked boolean NOT NULL,
    publisher uuid NOT NULL,
    lease_token_hash bytea,                   -- the lease is held by its token; only the hash is stored
    lease_holder uuid,
    lease_session uuid,                       -- for display; a write is never checked against it
    lease_expires_at timestamptz,
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    PRIMARY KEY (org_id, id),
    UNIQUE (org_id, audience_id, id),
    CONSTRAINT tasks_lease_whole CHECK (
      num_nonnulls(lease_token_hash, lease_holder, lease_session, lease_expires_at) IN (0, 4)
    ),
    CONSTRAINT tasks_lease_while_claimed CHECK ((state = 'claimed') = (lease_token_hash IS NOT NULL))
  )`,
  sql`CREATE INDEX tasks_by_project ON tasks (org_id, audience_id, project, updated_at)`,

  sql`CREATE TABLE task_notes (
    org_id uuid NOT NULL,
    task_id uuid NOT NULL,
    id uuid NOT NULL,
    audience_id uuid NOT NULL,
    kind text NOT NULL CHECK (kind IN ('note', 'handoff')),
    author uuid NOT NULL,
    session uuid NOT NULL,                    -- where it was written: its client's name is the session's
    text text NOT NULL,
    at timestamptz NOT NULL,
    PRIMARY KEY (org_id, task_id, id),
    FOREIGN KEY (org_id, audience_id, task_id) REFERENCES tasks (org_id, audience_id, id)
      ON UPDATE CASCADE ON DELETE CASCADE
  )`,
];

export const INIT_0001: Migration = {
  async up(db) {
    for (const statement of [...EXTENSIONS, ...DIRECTORY, ...FACTS, ...LOG, ...TASKS])
      await statement.execute(db);
  },
};
